        runEvictionScenario();
        runUpdateScenario();
        runValidationScenario();
        System.out.println("All cache checks passed.");
    }

    private static void runEvictionScenario() {
        LRUCache cache = new LRUCache(2);

        cache.put(1, 1);
        cache.put(2, 2);
        assertEquals("reads most recent entry", 1, cache.get(1));

        cache.put(3, 3);
        assertEquals("evicts least recently used entry", -1, cache.get(2));

        cache.put(4, 4);
        assertEquals("evicts older entry after another insert", -1, cache.get(1));
        assertEquals("retains recently used entry", 3, cache.get(3));
        assertEquals("returns newest entry", 4, cache.get(4));
    }

    private static void runUpdateScenario() {
        LRUCache cache = new LRUCache(2);

        cache.put(1, 1);
        cache.put(2, 2);
        cache.put(1, 10);
        cache.put(3, 3);

        assertEquals("keeps updated value", 10, cache.get(1));
        assertEquals("does not grow when updating an existing key", 2, cache.size());
        assertEquals("evicts the correct key after an update", -1, cache.get(2));
    }

    private static void runValidationScenario() {
        try {
            new LRUCache(0);
            throw new AssertionError("expected IllegalArgumentException for zero capacity");
        } catch (IllegalArgumentException expected) {
            // Expected path.
        }
    }

    private static void assertEquals(String description, int expected, int actual) {
        if (expected != actual) {
            throw new AssertionError(
                description + ": expected " + expected + ", but got " + actual
            );
        }
    }
}

import java.util.HashMap;
import java.util.Map;

public class LRUCache {
    private static final int NOT_FOUND = -1;

    private final int capacity;
    private final Map<Integer, Node> cache;
    private final UsageList usageList;

    public LRUCache(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("capacity must be greater than 0");
        }

        this.capacity = capacity;
        this.cache = new HashMap<>(capacity);
        this.usageList = new UsageList();
    }

    public int get(int key) {
        Node node = cache.get(key);
        if (node == null) {
            return NOT_FOUND;
        }

        usageList.moveToFront(node);
        return node.value;
    }

    public void put(int key, int value) {
        Node existingNode = cache.get(key);
        if (existingNode != null) {
            existingNode.value = value;
            usageList.moveToFront(existingNode);
            return;
        }

        Node newNode = new Node(key, value);
        cache.put(key, newNode);
        usageList.addFirst(newNode);

        if (cache.size() > capacity) {
            evictLeastRecentlyUsed();
        }
    }

    public int size() {
        return cache.size();
    }

    private void evictLeastRecentlyUsed() {
        Node leastRecentlyUsed = usageList.removeLast();
        if (leastRecentlyUsed != null) {
            cache.remove(leastRecentlyUsed.key);
        }
    }

    private static final class Node {
        private final int key;
        private int value;
        private Node next;
        private Node prev;

        private Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    private static final class UsageList {
        private final Node head = new Node(0, 0);
        private final Node tail = new Node(0, 0);

        private UsageList() {
            head.next = tail;
            tail.prev = head;
        }

        private void addFirst(Node node) {
            insertBetween(head, node, head.next);
        }

        private void moveToFront(Node node) {
            unlink(node);
            addFirst(node);
        }

        private Node removeLast() {
            Node leastRecentlyUsed = tail.prev;
            if (leastRecentlyUsed == head) {
                return null;
            }

            unlink(leastRecentlyUsed);
            return leastRecentlyUsed;
        }

        private void insertBetween(Node previous, Node node, Node next) {
            previous.next = node;
            node.prev = previous;
            node.next = next;
            next.prev = node;
        }

        private void unlink(Node node) {
            Node previous = node.prev;
            Node next = node.next;
            previous.next = next;
            next.prev = previous;
            node.prev = null;
            node.next = null;
        }
    }
}

